class Ledger {
  constructor() {
    this.accounts = new Map();
  }

  open(name) {
    if (this.accounts.has(name)) {
      throw new Error(`Account ${name} already exists`);
    }
    this.accounts.set(name, 0);
  }

  deposit(name, amount) {
    if (!this.accounts.has(name)) {
      throw new Error(`Unknown account ${name}`);
    }
    if (typeof amount !== 'number' || amount <= 0) {
      throw new Error(`Invalid deposit amount ${amount}`);
    }
    this.accounts.set(name, this.accounts.get(name) + amount);
  }

  balance(name) {
    if (!this.accounts.has(name)) {
      throw new Error(`Unknown account ${name}`);
    }
    return this.accounts.get(name);
  }
}

// Export the Ledger class
module.exports = { Ledger };

def words(text):
    """Return the list of lower-case words in order.
    A word is a run of letters and digits, and an apostrophe between two letters stays inside the word.
    """
    if not text:
        return []

    result = []
    current_word = ""

    i = 0
    while i < len(text):
        char = text[i]
        if char.isalnum() or char == "'":
            current_word += char
        else:
            if current_word:
                result.append(current_word.lower())
                current_word = ""
        i += 1

    # Don't forget the last word
    if current_word:
        result.append(current_word.lower())

    return result

def word_count(text):
    """Return a dict of word to count."""
    word_list = words(text)
    count_dict = {}
    for word in word_list:
        count_dict[word] = count_dict.get(word, 0) + 1
    return count_dict

if __name__ == "__main__":
