    assert words("Don't stop!") == ["don't", "stop"]
    assert words("One, two, three.") == ["one", "two", "three"]
    assert words("123 abc 456") == ["123", "abc", "456"]
    assert words("") == []
    assert words("   ") == []
    assert words("a'b") == ["a'b"]
    assert words("a'b'c") == ["a'b'c"]

    assert word_count("Hello, world!") == {"hello": 1, "world": 1}
