class Store:
    def __init__(self):
        self._data = {}

    def set(self, key, value):
        self._data[key] = value

    def get(self, key, default=None):
        return self._data.get(key, default)

    def delete(self, key):
        if key in self._data:
            del self._data[key]
            return True
        return False

    def keys(self):
        return sorted(self._data.keys())

if __name__ == "__main__":
    # Test the Store class
    store = Store()

    # Test set and get
    store.set("name", "Alice")
    assert store.get("name") == "Alice"
    assert store.get("age", 25) == 25  # default value

    # Test delete
    assert store.delete("name") == True
    assert store.get("name") is None
    assert store.delete("nonexistent") == False

    # Test keys
    store.set("zebra", 1)
    store.set("apple", 2)
    store.set("banana", 3)
    assert store.keys() == ["apple", "banana", "zebra"]

