import datetime

def parse(s):
    """Parse a 'YYYY-MM-DD' string into a datetime.date.

    Raises ValueError for invalid formats or impossible dates.
    """
    try:
        return datetime.datetime.strptime(s, '%Y-%m-%d').date()
    except ValueError:
        raise ValueError("Invalid date format or impossible date")

def fmt(d):
    """Format a datetime.date into 'YYYY-MM-DD' string."""
    return d.strftime('%Y-%m-%d')

if __name__ == "__main__":
    # Test cases from the problem description
    assert parse("2026-01-01") == datetime.date(2026, 1, 1)
    assert parse("2026-12-31") == datetime.date(2026, 12, 31)
    assert fmt(datetime.date(2026, 1, 1)) == "2026-01-01"
    assert fmt(datetime.date(2026, 12, 31)) == "2026-12-31"

