class Store:
    def __init__(self):
        self._data = {}
        self._transaction = None

    def begin(self):
        if self._transaction is not None:
            raise RuntimeError("Transaction already in progress")
        self._transaction = dict(self._data)

    def commit(self):
        if self._transaction is None:
            raise RuntimeError("No transaction in progress")
        self._transaction = None

    def rollback(self):
        if self._transaction is None:
            raise RuntimeError("No transaction in progress")
        self._data = dict(self._transaction)
        self._transaction = None

    def set(self, key, value):
        self._data[key] = value

    def get(self, key, default=None):
        return self._data.get(key, default)

    def delete(self, key):
        if key in self._data:
            del self._data[key]
            return True
        return False

    def keys(self):
        return sorted(self._data.keys())

def fmt(d):
    """Format a datetime.date into 'YYYY-MM-DD' string."""
    return d.strftime('%Y-%m-%d')

def add_days(s, n):
    """Return the 'YYYY-MM-DD' date n days after s (n may be negative).

    Args:
        s (str): A date string in 'YYYY-MM-DD' format
        n (int): Number of days to add (can be negative)

    Returns:
        str: The resulting date in 'YYYY-MM-DD' format
    """
    d = parse(s)
    new_date = d + datetime.timedelta(days=n)
    return fmt(new_date)

