    order() {
        // Create a copy of dependencies to avoid modifying the original
        const inDegree = new Map();
        const graph = new Map();

        // Initialize in-degree map and adjacency list
        for (const [id] of this.tasks) {
            inDegree.set(id, 0);
            graph.set(id, []);
        }

        // Calculate in-degrees and build adjacency list
        for (const [id, deps] of this.dependencies) {
            for (const dep of deps) {
                inDegree.set(id, inDegree.get(id) + 1);
                if (!graph.has(dep)) {
                    graph.set(dep, []);
                }
                graph.get(dep).push(id);
            }
        }

        // Initialize queue with tasks that have no dependencies
        const queue = [];
        const result = [];

        for (const [id, degree] of inDegree) {
            if (degree === 0) {
                queue.push(id);
            }
        }

        // Process tasks in topological order
        while (queue.length > 0) {
            // Get the first task (FIFO order)
            const id = queue.shift();
            result.push(id);

            // For each dependent task, reduce its in-degree
            if (graph.has(id)) {
                for (const dependent of graph.get(id)) {
                    inDegree.set(dependent, inDegree.get(dependent) - 1);
                    // If in-degree becomes 0, add to queue
                    if (inDegree.get(dependent) === 0) {
                        queue.push(dependent);
                    }
                }
            }
        }

        // Check for cycles
        if (result.length !== this.tasks.size) {
            throw new Error('Cycle detected in task dependencies');
        }

        return result;
    }

    totalTime() {
        // If there are no tasks, return 0
        if (this.tasks.size === 0) {
            return 0;
        }

        // Calculate the maximum time to complete all tasks in parallel
        // We need to find the critical path - the longest path through the dependency graph
        const taskTimes = new Map();

        // Initialize task times with their durations
        for (const [id, duration] of this.tasks) {
            taskTimes.set(id, duration);
        }

        // Process tasks in topological order to find the maximum time
        const orderedTasks = this.order();

        for (const taskId of orderedTasks) {
            // Get the dependencies of this task
            const deps = this.dependencies.get(taskId) || [];

            // For each dependency, update the task time if necessary
            for (const depId of deps) {
                // The time to complete this task is the maximum of:
                // 1. Current time for this task
                // 2. Time to complete dependency + duration of dependency
                const depTime = taskTimes.get(depId);
                const currentTime = taskTimes.get(taskId);
                taskTimes.set(taskId, Math.max(currentTime, depTime + this.tasks.get(depId)));
            }
        }

        // The total time is the maximum time among all tasks
        let maxTime = 0;
        for (const time of taskTimes.values()) {
            maxTime = Math.max(maxTime, time);
        }

        return maxTime;
    }
}

